\label{lem:hs-composition}
Let $\mathfrak B:(\mathbb R^p)^2\to\mathbb R$ be bilinear and let $A_1,A_2\in \mathbb R^{p \times p}$. Define
\begin{equation}
    \mathfrak B_{A_1,A_2}(u_1,u_2) \mathrel{\mathop{:}}= \mathfrak B(A_1u_1,A_2u_2).
\end{equation}
Then
\begin{equation}\label{eq:hs-compose-bilinear}
    \left\lVert \mathfrak B_{A_1,A_2}\right\rVert_\mathrm{HS}
    \le \left\lVert \mathfrak B\right\rVert_\mathrm{HS} \left\lVert A_1\right\rVert_\mathrm{op} \left\lVert A_2\right\rVert_\mathrm{op}.
\end{equation}
If $\mathfrak T:(\mathbb R^p)^3\to\mathbb R$ is trilinear and $A_1,A_2,A_3:\mathbb R^p\to\mathbb R^p$ are linear, then
\begin{equation}\label{eq:hs-compose-trilinear-direct}
    \left\lVert \mathfrak T(A_1\cdot,A_2\cdot,A_3\cdot)\right\rVert_\mathrm{HS}
    \le \left\lVert \mathfrak T\right\rVert_\mathrm{HS} \left\lVert A_1\right\rVert_\mathrm{op} \left\lVert A_2\right\rVert_\mathrm{op} \left\lVert A_3\right\rVert_\mathrm{op}.
\end{equation}
Now let $\mathbf{B}:(\mathbb R^p)^2\to\mathbb R^p$ be bilinear and suppose that for some $K<\infty$,
\begin{equation}\label{eq:hs-compose-hyp}
    \left\lVert \left\langle w,\mathbf{B}(\cdot,\cdot)\right\rangle\right\rVert_\mathrm{HS} \le K \left\lVert w\right\rVert
    \qquad \text{for every } w\in\mathbb R^p.
\end{equation}
Let $A,U,V,W:\mathbb R^p\to\mathbb R^p$ be linear and define
\begin{equation}
    \mathfrak C(u_1,u_2,u_3)
    \mathrel{\mathop{:}}=
    \mathfrak B\big(Au_1, U\mathbf{B}(Vu_2,Wu_3)\big).
\end{equation}
Then
\begin{equation}\label{eq:hs-compose-trilinear}
    \left\lVert \mathfrak C\right\rVert_\mathrm{HS}
    \le K \left\lVert \mathfrak B\right\rVert_\mathrm{HS} \left\lVert A\right\rVert_\mathrm{op} \left\lVert U\right\rVert_\mathrm{op} \left\lVert V\right\rVert_\mathrm{op} \left\lVert W\right\rVert_\mathrm{op}.
\end{equation}

Choose a smooth cutoff $\chi_L$ that equals one on $[-L,L]$ and is supported on $[-L-1,L+1]$, and set $\bar\psi=\chi_L\psi$. Its first three derivatives are bounded by a constant depending only on $L$ and on the corresponding local bounds for $\psi$. Moreover,
    \begin{equation*}
        A+sE=(1-s)A+s(A+E),
        \qquad 0\leq s\leq1,
    \end{equation*}
    so \eqref{eq:smooth-spectral-local-domain} and convexity of the operator norm imply $\|A+sE\|_\mathrm{op}\leq L$. Hence $\psi$ and $\bar\psi$ induce the same spectral functional along the entire segment from $A$ to $A+E$. It is therefore enough to prove the claim for the bounded $C^3$ function $\bar\psi$; to simplify notation, we again denote it by $\psi$.

    Lemma \ref{lem:dk-bounds} implies that the matrix map $A\mapsto \psi(A)$ is $C^3$; hence the normalized trace functional $\Phi_\psi$ is $C^3$ on $\textsf{Sym}_d$.

    We first identify the linear term. If
    $A=\sum_{a=1}^d \lambda_a P_a$ is a spectral decomposition of
    $A$, then the first-order Daleckii--Krein formula gives
    \begin{equation}
        D(\psi(\cdot))(A)[E]
        =
        \sum_{a,b=1}^d \psi^{[1]}(\lambda_a,\lambda_b)P_a E P_b.
    \end{equation}
    Taking traces and using cyclic invariance leaves only the terms $a=b$, and
    $\psi^{[1]}(\lambda_a,\lambda_a)=\psi'(\lambda_a)$. Therefore
    \begin{equation}\label{eq:Phi-linear-term}
        D\Phi_\psi(A)[E]
        =\frac1d\mathrm{Tr}\big(\psi'(A)E\big).
    \end{equation}

    Define the symmetric bilinear form
    \begin{equation}
        B_{\psi,A}(H_1,H_2)\mathrel{\mathop{:}}= \frac12 D^2\Phi_\psi(A)[H_1,H_2].
    \end{equation}
    Differentiating \eqref{eq:Phi-linear-term} in the direction $H_1$ and
    testing against $H_2$ gives
    \begin{equation}\label{eq:Phi-Hessian-trace}
        D^2\Phi_\psi(A)[H_1,H_2]
        =\frac1d\mathrm{Tr}\big(D(\psi') (A)[H_1]H_2\big).
    \end{equation}
    Hence, by Cauchy--Schwarz and Lemma \ref{lem:dk-bounds} applied to
    $\psi'$ with $m=1$,
    \begin{equation}
        \left\lvert D^2\Phi_\psi(A)[H_1,H_2]\right\rvert
        \le C_\psi d^{-1}\left\lVert H_1\right\rVert_{\mathrm{F}}\left\lVert H_2\right\rVert_{\mathrm{F}}.
    \end{equation}
    The Riesz representation theorem on the inner product space $(\textsf{Sym}_d,\langle\cdot,
    \cdot\rangle_\mathrm{F})$ therefore gives a unique self-adjoint linear operator
    $\mathcal K_{\psi,A}:\textsf{Sym}_d\to\textsf{Sym}_d$ such that
    \begin{equation}
        B_{\psi,A}(H_1,H_2)=\left\langle H_1,\mathcal K_{\psi,A}(H_2)\right\rangle,
        \qquad H_1,H_2\in\textsf{Sym}_d,
    \end{equation}
    and
    \begin{equation}
        \left\lVert \mathcal K_{\psi,A}\right\rVert_{\mathrm{F}\to\mathrm{F}}\le C_\psi d^{-1}.
    \end{equation}
    Thus
    \begin{equation}
        Q_{\psi,A}(E)\mathrel{\mathop{:}}= B_{\psi,A}(E,E)
        =\left\langle E,\mathcal K_{\psi,A}(E)\right\rangle
        =\frac12D^2\Phi_\psi(A)[E,E].
    \end{equation}

    Taylor's theorem with integral remainder gives
    \begin{equation}
        \Phi_\psi(A+E)-\Phi_\psi(A)-D\Phi_\psi(A)[E]-\frac12D^2\Phi_\psi(A)[E,E]
        =
        \int_0^1 \frac{(1-s)^2}{2}D^3\Phi_\psi(A+sE)[E,E,E]ds.
    \end{equation}
    We define the right-hand side to be $R_{\psi,A}(E)$. Differentiating
    \eqref{eq:Phi-Hessian-trace} once more, and using symmetry of higher
    derivatives, yields
    \begin{equation}
        D^3\Phi_\psi(B)[H_1,H_2,H_3]
        =
        \frac1d\mathrm{Tr}\big(D^2(\psi')(B)[H_1,H_2]H_3\big).
    \end{equation}
    Applying Lemma \ref{lem:dk-bounds} to $\psi'$ with $m=2$ and then
    Cauchy--Schwarz gives
    \begin{equation}
        \left\lvert D^3\Phi_\psi(B)[H_1,H_2,H_3]\right\rvert
        \le C_\psi d^{-1}
        \left\lVert H_1\right\rVert_{\mathrm{F}}\left\lVert H_2\right\rVert_{\mathrm{F}}\left\lVert H_3\right\rVert_{\mathrm{F}}.
    \end{equation}
    Consequently
    \begin{equation}
        \left\lvert R_{\psi,A}(E)\right\rvert\le C_\psi d^{-1}\left\lVert E\right\rVert_{\mathrm{F}}^3,
    \end{equation}
    which is \eqref{eq:smooth-spectral-remainder-bound}. This proves
    \eqref{eq:smooth-spectral-taylor}.

    For the vector form, let
    \begin{equation}
        K_{\psi,A}\mathrel{\mathop{:}}= \operatorname{vec}\circ \mathcal K_{\psi,A}\circ \mathrm{mat},
    \end{equation}
    viewed as its matrix in the standard Euclidean coordinates of $\mathbb R^p$.
    Since $\operatorname{vec}$ is an isometry, $K_{\psi,A}$ is symmetric and has the same
    operator norm as $\mathcal K_{\psi,A}$. Finally,
    \begin{equation}
        d^{-1}\left\lVert \psi'(A)\right\rVert_{\mathrm{F}}
        \le d^{-1}\sqrt d\,\left\lVert \psi'\right\rVert_\infty
        =d^{-1/2}\left\lVert \psi'\right\rVert_\infty,
    \end{equation}
    and the final claim follows immediately from
    \eqref{eq:smooth-spectral-remainder-bound}.

Fix $t$, write $\varphi=\sigma_t$ and $G=G_t$. Since
    $\varphi\in C_b^4(\mathbb R)$ and $\left\lVert \varphi^{(r)}\right\rVert_\infty\le M_{\sigma,4}$ for
    $1\le r\le4$, Lemma \ref{lem:dk-bounds} implies that $G$ is $C^4$ and
    \begin{equation}\label{eq:G-derivative-bounds-up-to-4}
        \sup_{z\in\mathbb R^p}\left\lVert D^rG(z)\right\rVert_{\mathrm{op}}\le M_{\sigma,4},
        \qquad 1\le r\le 4.
    \end{equation}

    Define
    \begin{equation}
        \mathbf{B}_{t,y}(g_1,g_2) \mathrel{\mathop{:}}= \frac12 D^2G(y)[g_1,g_2],
    \end{equation}
    \begin{equation}
        \mathbf{T}_{t,y}(g_1,g_2,g_3) \mathrel{\mathop{:}}= \frac16 D^3G(y)[g_1,g_2,g_3],
    \end{equation}
    and
    \begin{equation}
        \rho_{t,y}^{(4)}(g)
        \mathrel{\mathop{:}}=
        \int_0^1 \frac{(1-s)^3}{6} D^4G(y+sg)[g,g,g,g] ds.
    \end{equation}
    Taylor's theorem with integral remainder gives
    \eqref{eq:local-spectral-third-order}.  The pointwise bounds \eqref{eq:local-spectral-B-bound}--\eqref{eq:local-spectral-rem-bound} follow immediately from \eqref{eq:G-derivative-bounds-up-to-4}.

    It remains to prove the Hilbert--Schmidt bounds. Fix $w\in\mathbb R^p$ and write $W=\mathrm{mat}(w)$. Let
    \begin{equation}
        Y \,\mathrel{\mathop{:}}=\, \mathrm{mat}(y) \,=\, \sum_{a\,=\,1}^d \lambda_a P_a,
        \qquad P_a = u_a u_a^\top,
    \end{equation}
    with eigenvalues repeated according to multiplicity. For matrices
    $H_j=\mathrm{mat}(g_j)$, the second-order Daleckii--Krein formula in Lemma \ref{lem:dk-bounds} gives
    \begin{equation}
        \left\langle w,D^2G(y)[g_1,g_2]\right\rangle
        =
        \sum_{\pi\in S_2}
        \sum_{a,b,c=1}^d
        \varphi^{[2]}(\lambda_a,\lambda_b,\lambda_c)
        \mathrm{Tr}(WP_a H_{\pi(1)} P_b H_{\pi(2)} P_c).
    \end{equation}
    Define the ordered bilinear form on the full matrix space $\mathbb R^{d\times d}$ by
    \begin{equation}
        \mathfrak B_{y,w}(H_1,H_2)
        \mathrel{\mathop{:}}=
        \sum_{a,b,c=1}^d
        \varphi^{[2]}(\lambda_a,\lambda_b,\lambda_c)
        \mathrm{Tr}(WP_a H_1 P_b H_2 P_c).
    \end{equation}
    Since $\mathbf{B}_{t,y}=\frac12D^2G(y)$,
    \begin{equation}
        \left\langle w,\mathbf{B}_{t,y}(g_1,g_2)\right\rangle
        =\frac12\Big(\mathfrak B_{y,w}(H_1,H_2)+\mathfrak B_{y,w}(H_2,H_1)\Big).
    \end{equation}
    Permuting arguments preserves Hilbert--Schmidt norm, and restricting a
    multilinear form from $\mathbb R^{d\times d}$ to the subspace $\textsf{Sym}_d$ cannot
    increase its Hilbert--Schmidt norm. Thus
    \begin{equation}\label{eq:B-scalar-HS-reduce}
        \big\|\left\langle w,\mathbf{B}_{t,y}(\cdot,\cdot)\right\rangle\big\|_{\mathrm{HS}}
        \le \left\lVert \mathfrak B_{y,w}\right\rVert_{\mathrm{HS}(\mathbb R^{d\times d})}.
    \end{equation}

    Let
    \begin{equation}
        \mathsf{E}_{ab}\mathrel{\mathop{:}}= u_a u_b^\top,
        \qquad 1\le a,b\le d.
    \end{equation}
    Then $(\mathsf{E}_{ab})_{a,b}$ is a Frobenius-orthonormal basis of
    $\mathbb R^{d\times d}$. A direct computation shows that
    \begin{equation}
        \mathfrak B_{y,w}(\mathsf{E}_{ab},\mathsf{E}_{bc})
        =
        \varphi^{[2]}(\lambda_a,\lambda_b,\lambda_c)(u_c^\top W u_a),
    \end{equation}
    while $\mathfrak B_{y,w}(\mathsf{E}_{rs},\mathsf{E}_{tu})=0$ unless $s=t$. Hence
    \begin{equation}
        \left\lVert \mathfrak B_{y,w}\right\rVert_{\mathrm{HS}}^2
        =
        \sum_{a,b,c=1}^d
        \left\lvert \varphi^{[2]}(\lambda_a,\lambda_b,\lambda_c)\right\rvert^2
        \left\lvert u_c^\top W u_a\right\rvert^2
        \le C d\left\lVert W\right\rVert_{\mathrm{F}}^2
        = C d\left\lVert w\right\rVert^2.
    \end{equation}
    Combining this with \eqref{eq:B-scalar-HS-reduce} proves
    \eqref{eq:local-spectral-B-HS}.

    The trilinear estimate is analogous. Define the trilinear form on
    $\mathbb R^{d\times d}$ by
    \begin{equation}
        \mathfrak T_{y,w}(H_1,H_2,H_3)
        \mathrel{\mathop{:}}=
        \sum_{a,b,c,e=1}^d
        \varphi^{[3]}(\lambda_a,\lambda_b,\lambda_c,\lambda_e)
        \mathrm{Tr}(WP_a H_1 P_b H_2 P_c H_3 P_e).
    \end{equation}
    Since $\mathbf{T}_{t,y}=\frac16D^3G(y)$,
    $\left\langle w,\mathbf{T}_{t,y}(\cdot,\cdot,\cdot)\right\rangle$ is the average over the six
    permutations of the arguments of $\mathfrak T_{y,w}$, restricted to $\textsf{Sym}_d$. Hence
    \begin{equation}
        \big\|\left\langle w,\mathbf{T}_{t,y}(\cdot,\cdot,\cdot)\right\rangle\big\|_{\mathrm{HS}}
        \le \left\lVert \mathfrak T_{y,w}\right\rVert_{\mathrm{HS}(\mathbb R^{d\times d})}.
    \end{equation}
    Moreover,
    \begin{equation}
        \mathfrak T_{y,w}(\mathsf{E}_{ab},\mathsf{E}_{bc},\mathsf{E}_{ce})
        =
        \varphi^{[3]}(\lambda_a,\lambda_b,\lambda_c,\lambda_e)(u_e^\top W u_a),
    \end{equation}
    and the form vanishes on all other triples of matrix units. Therefore
    \begin{equation}
        \left\lVert \mathfrak T_{y,w}\right\rVert_{\mathrm{HS}}^2
        \le C d^2\left\lVert W\right\rVert_{\mathrm{F}}^2
        = C d^2\left\lVert w\right\rVert^2.
    \end{equation}
    This proves \eqref{eq:local-spectral-T-HS}.

Let $L$ be the matrix representation of the scalar bilinear form $\mathfrak B$, so
    $\mathfrak B(x,y)=\left\langle x,Ly\right\rangle$ and $\left\lVert \mathfrak B\right\rVert_\mathrm{HS}=\left\lVert L\right\rVert_\mathrm{F}$. Then
    \begin{equation}
        \mathfrak B_{A_1,A_2}(u_1,u_2)=\left\langle u_1,A_1^\top L A_2 u_2\right\rangle,
    \end{equation}
    and therefore
    \begin{equation}
        \left\lVert \mathfrak B_{A_1,A_2}\right\rVert_\mathrm{HS}
        =\left\lVert A_1^\top L A_2\right\rVert_\mathrm{F}
        \le \left\lVert L\right\rVert_\mathrm{F}\left\lVert A_1\right\rVert_\mathrm{op}\left\lVert A_2\right\rVert_\mathrm{op},
    \end{equation}
    proving \eqref{eq:hs-compose-bilinear}.

    For \eqref{eq:hs-compose-trilinear-direct}, identify $\mathfrak T$ with its
    coefficient tensor $T=(T_{abc})$ in the standard orthonormal basis. The
    coefficient tensor of $\mathfrak T(A_1\cdot,A_2\cdot,A_3\cdot)$ is
    $(A_1^\top\otimes A_2^\top\otimes A_3^\top)T$ after vectorization. Hence
    \begin{equation}
        \left\lVert \mathfrak T(A_1\cdot,A_2\cdot,A_3\cdot)\right\rVert_\mathrm{HS}
        \le
        \left\lVert A_1^\top\otimes A_2^\top\otimes A_3^\top\right\rVert_\mathrm{op}\left\lVert \mathfrak T\right\rVert_\mathrm{HS}
        =
        \left\lVert A_1\right\rVert_\mathrm{op}\left\lVert A_2\right\rVert_\mathrm{op}\left\lVert A_3\right\rVert_\mathrm{op}\left\lVert \mathfrak T\right\rVert_\mathrm{HS}.
    \end{equation}

    We now prove \eqref{eq:hs-compose-trilinear}. Let $L$ again represent
    $\mathfrak B$. For each standard basis vector $e_a$, define the scalar bilinear form
    \begin{equation}
        G_a(u_2,u_3)\mathrel{\mathop{:}}= \left\langle U^\top L^\top A e_a,\mathbf{B}(u_2,u_3)\right\rangle.
    \end{equation}
    Then
    \begin{equation}
        \mathfrak C(e_a,u_2,u_3)=G_a(Vu_2,Wu_3).
    \end{equation}
    By \eqref{eq:hs-compose-hyp},
    \begin{equation}
        \left\lVert G_a\right\rVert_\mathrm{HS}
        \le K\left\lVert U^\top L^\top A e_a\right\rVert
        \le K\left\lVert U\right\rVert_\mathrm{op}\left\lVert L^\top A e_a\right\rVert.
    \end{equation}
    Applying the already proved bilinear composition bound to $G_a$ gives
    \begin{equation}
        \left\lVert \mathfrak C(e_a,\cdot,\cdot)\right\rVert_\mathrm{HS}
        \le
        K\left\lVert U\right\rVert_\mathrm{op}\left\lVert V\right\rVert_\mathrm{op}\left\lVert W\right\rVert_\mathrm{op}\left\lVert L^\top A e_a\right\rVert.
    \end{equation}
    Summing over $a$ yields
    \begin{equation}
        \begin{aligned}
        \left\lVert \mathfrak C\right\rVert_\mathrm{HS}^2
        &=\sum_{a=1}^p\left\lVert \mathfrak C(e_a,\cdot,\cdot)\right\rVert_\mathrm{HS}^2 \\
        &\le K^2\left\lVert U\right\rVert_\mathrm{op}^2\left\lVert V\right\rVert_\mathrm{op}^2\left\lVert W\right\rVert_\mathrm{op}^2
        \sum_{a=1}^p\left\lVert L^\top A e_a\right\rVert^2 \\
        &=K^2\left\lVert U\right\rVert_\mathrm{op}^2\left\lVert V\right\rVert_\mathrm{op}^2\left\lVert W\right\rVert_\mathrm{op}^2\left\lVert L^\top A\right\rVert_\mathrm{F}^2 \\
        &\le K^2\left\lVert \mathfrak B\right\rVert_\mathrm{HS}^2\left\lVert A\right\rVert_\mathrm{op}^2\left\lVert U\right\rVert_\mathrm{op}^2\left\lVert V\right\rVert_\mathrm{op}^2\left\lVert W\right\rVert_\mathrm{op}^2.
        \end{aligned}
    \end{equation}
    Taking square roots proves \eqref{eq:hs-compose-trilinear}.

\label{lem:adamczak-opnorm}
    Let $X_1, \ldots, X_N \in \mathbb R^p$ be independent centered isotropic random vectors. Assume that for some constants $\psi, K, c > 0$, we have
    \begin{equation}
        \sup_{j \,\le\, N} \sup_{y \,\in\, S^{p-1}} \left\lVert \left\langle X_j,y\right\rangle\right\rVert_{\psi_1} \,\le\, \psi
    \end{equation}
    and
    \begin{equation}
        \mathbb P\left(\max_{j\,\le\, N}\frac{\|X_j\|}{\sqrt p}\,>\, K\max\left\{1,\left(\frac{N}{p}\right)^{1/4}\right\}\right)\,\le\, e^{-c\sqrt p}.
    \end{equation}
    Let $A = [X_1, \ldots, X_N] \in \mathbb R^{p \times N}$, then
    \begin{equation}
        \mathbb P(\left\lVert A\right\rVert_\mathrm{op} > C \sqrt{p}) \le 2 e^{-c'\sqrt{p}}
    \end{equation}
    for some constants $C,c'>0$ depending only on $\psi,K$ and an upper bound for $N/p$.

\label{lem:sensing-envelope}
    For any fixed $m \ge 1$, there exists $C_m < \infty$ such that uniformly in $i$,
    \begin{equation}
        \left\lVert K_i\right\rVert_{L^m(\mathrm{op})} \leq C_m, \quad \left\lVert F_{\setminus i} \epsilon\right\rVert_{L^m} \leq C_m d
    \end{equation}
    Moreover, for $u \in \{f_i, \widetilde f_i\}$,
    \begin{equation}
        \|u\|_{L^m} \leq C_m.
    \end{equation}

\label{lem:one-column-moments}
    Let $u\in\{f_i,\widetilde f_i\}$. Let $a,b\in\mathbb R^p$ and $A\in\mathbb R^{p\times p}$ be $\mathcal G_i$-measurable, and let $A_{\mathrm s}=(A+A^\top)/2$.
    Then almost surely,
    \begin{equation}\label{eq:linear-moment-1}
        \mathbb{E}[\left\langle u,a\right\rangle\mid \mathcal G_i]=0
    \end{equation}
    \begin{equation}\label{eq:linear-moment-2}
        \mathbb{E}[\left\langle u,a\right\rangle\left\langle u,b\right\rangle\mid \mathcal G_i]=\frac1p\left\langle a,b\right\rangle
    \end{equation}
    Moreover, for every integer $m\ge 1$ there exists $C_m<\infty$ such that almost surely,
    \begin{equation}\label{eq:linear-moment-lm}
        \mathbb{E}\left[\left\lvert \left\langle u,a\right\rangle\right\rvert^m\mid \mathcal G_i\right]\le C_m p^{-m/2}\left\lVert a\right\rVert^m
    \end{equation}
    \begin{equation}\label{eq:quadratic-moment-lm}
        \mathbb{E}\left[\left\lvert \left\langle u,Au\right\rangle-\frac1p\mathrm{Tr} A\right\rvert^m\mid \mathcal G_i\right]
        \le C_m d^{-m/2}\left\lVert A_{\mathrm s}\right\rVert_{\mathrm{op}}^m
    \end{equation}
    Consequently, after averaging over $\mathcal G_i$,
    \begin{equation}\label{eq:linear-moment-uncond}
        \left\lVert \left\langle u,a\right\rangle\right\rVert_{L^m}\le C_m d^{-1}\left\lVert a\right\rVert_{L^m}
    \end{equation}
    \begin{equation}\label{eq:quadratic-moment-uncond}
        \left\|\left\langle u,Au\right\rangle-\frac1p\mathrm{Tr} A\right\|_{L^m}
        \le C_m d^{-1/2}\left\lVert A_{\mathrm s}\right\rVert_{L^{2m}(\mathrm{op})}
    \end{equation}

\label{cor:one-column-moments}
For every integer $m\ge 1$ there exists $C_m<\infty$ such that the following hold uniformly in $i$ and in $u\in\{f_i,\widetilde f_i\}$.
\begin{enumerate}[label=(\roman*)]
    \item If $a$ is $\mathcal G_i$-measurable, then
    \begin{equation}
        \left\lVert \left\langle u,a\right\rangle\right\rVert_{L^m}\le C_m d^{-1}\left\lVert a\right\rVert_{L^m}.
    \end{equation}
    In particular, if $\left\lVert a\right\rVert_{L^m}\le C d^{-1/2}$, then
    \begin{equation}
        \left\lVert \left\langle u,a\right\rangle\right\rVert_{L^m}\le C_m d^{-3/2}.
    \end{equation}
    \item If $A$ is $\mathcal G_i$-measurable and $A_{\mathrm s}=(A+A^\top)/2$, then
    \begin{equation}
        \left\|\left\langle u,Au\right\rangle-\frac1p\mathrm{Tr} A\right\|_{L^m}\le C_m d^{-1/2}\left\lVert A_{\mathrm s}\right\rVert_{L^{2m}(\mathrm{op})}.
    \end{equation}
    In particular, if $\left\lVert A_{\mathrm s}\right\rVert_{L^{2m}(\mathrm{op})}\le C$, then
    \begin{equation}
        \left\|\left\langle u,Au\right\rangle-\frac1p\mathrm{Tr} A\right\|_{L^m}\le C_m d^{-1/2},
    \end{equation}
    while if $\left\lVert A_{\mathrm s}\right\rVert_{L^{2m}(\mathrm{op})}\le C d^{-1}$, then
    \begin{equation}
        \left\|\left\langle u,Au\right\rangle-\frac1p\mathrm{Tr} A\right\|_{L^m}\le C_m d^{-3/2}.
    \end{equation}
\end{enumerate}

\label{lem:refined-centered-quad}
    For every integer $m \ge 2$ there exists $C_m < \infty$ such that the following holds uniformly in $i$ and in $u \in \{f_i, \widetilde f_i\}$. If $A \in \mathbb R^{p \times p}$ is $\mathcal{G}_i$-measurable and $A_s = \frac{A + A^\top}{2}$, then we have
    \begin{equation}\label{eq:refined-centered-quad-bound}
        \left\lVert u^\top A u - \frac 1 p \mathrm{Tr} A\right\rVert_{L^m} \le C_m d^{-3/2} \left\lVert A_s\right\rVert_{L^{2m}(\mathrm{F})}
    \end{equation}
    In particular, if $\left\lVert A\right\rVert_{L^{2m}(\mathrm{F})} \le C d^{-1/2}$, then
    \begin{equation}
        \left\lVert  u^\top A u - \frac 1 p \mathrm{Tr} A\right\rVert_{L^m} \le C_m d^{-2}
    \end{equation}

\label{lem:gaussian-quad-cumulants}
    Let $x \sim \mathcal{N}(0, I_d)$. Let $M \in \textsf{Sym}_d$ and define
    \begin{equation}
        q_M(x) = x^\top M x - \mathrm{Tr}(M)
    \end{equation}
    For random variables $X_1, \ldots, X_r$ define their joint cumulant by
    \begin{equation}
        \kappa(Z_1, \ldots, Z_r) \,\mathrel{\mathop{:}}=\, \partial_{t_1} \cdots \partial_{t_r} \log \mathbb{E} \exp\left( \sum_{j \,=\, 1}^t t_j X_j  \right)\Bigg|_{t \,=\, 0}
    \end{equation}
    Then for every integer $ r \ge 2$ and every $M_1, \cdots, M_r \in \textsf{Sym}_d$, we have
    \begin{equation}
        \kappa\left(q_{M_1}(x), \ldots, q_{M_r}(x) \right) \,=\, 2^{r-1} \sum_{\sigma \,\in\, \mathfrak C_r} \mathrm{Tr}\left( M_{\sigma(1)} \cdots M_{\sigma(r)} \right)
    \end{equation}
    where $\mathfrak C_r$ is $S_r$ quotient by the equivalence of differing by a cycle. In particular, we have
    \begin{equation}
        \kappa(q_M(x), q_N(x)) = 2 \mathrm{Tr}(MN)
    \end{equation}
    \begin{equation}
        \kappa\left( q_{M_1}(x), q_{M_2}(x), q_{M_3}(x), q_{M_4}(x) \right) \,=\, 8 \sum_{\sigma \,\in\, \mathfrak C_4} \mathrm{Tr}(M_{\sigma(1)}M_{\sigma(2)} M_{\sigma(3)} M_{\sigma(4)})
    \end{equation}

We first prove the $m$th-moment bound for the sensing vector norm. If $u = \widetilde f_i \sim \mathcal{N}(0, I_p/p)$, then we have $p\|u\|^2 \sim \chi_p^2$. Therefore, $\|u\|_{L^m} \leq C_m$ for every $m \geq 1$. If $u = f_i$, then
    \begin{equation}
        \|u\|^2 \,=\, \frac{1}{d(d + 1)} \left\lVert x_ix_i^\top - I_d\right\rVert_\mathrm{F}^2 \,=\, \frac{\left\lVert x_i\right\rVert^4 - 2 \left\lVert x_i\right\rVert^2 + d}{d(d + 1)}.
    \end{equation}
    Observe that $\left\lVert x_i\right\rVert^2 \sim \chi_d^2$. Therefore, the RHS has every moment bounded uniformly in $d$. So $\|u\|_{L^m} \leq C_m$. Next, denote the non-leave-one-out columns by
    \begin{equation}
        v_j^{(i)} \mathrel{\mathop{:}}= \begin{cases}
            \widetilde f_j, & 1 \leq j < i \\
            f_j, & i < j \leq n
        \end{cases}
    \end{equation}
    and let $V_i \mathrel{\mathop{:}}= [v_j^{(i)}]_{j \neq i} \in \mathbb R^{p \times (n - 1)}$. By the definition of $K_i$ in \eqref{eq:Ki-def}, we write $K_i = V_iV_i^\top$. Set $X_j^{(i)} = \sqrt{p}\, v_j^{(i)}$. For the Gaussian columns, we have
    \begin{equation}
        \sup_{y \,\in\, S^{p-1}} \left\lVert \left\langle  X_j^{(i)},y\right\rangle\right\rVert_{\psi_1} \,\leq\, \|\mathcal{N}(0,1)\|_{\psi_1} \,\leq\, C
    \end{equation}
    where $\left\lVert \cdot\right\rVert_{\psi_1}$ denotes the sub-exponential norm. In particular, $\frac{\left\lVert X_j^{(i)}\right\rVert}{\sqrt{p}}$ has sub-exponential tails with constants independent of $d$. For the RO columns, if $y = \operatorname{vec}(M)$ with $\left\lVert M\right\rVert_\mathrm{F} = 1$, then
    \begin{equation}
        \left\langle X_j^{(i)},y\right\rangle = \frac{x_j^\top M x_j - \mathrm{Tr} M}{\sqrt{2}}.
    \end{equation}
    Writing $M = U \Lambda U^\top$, this is a linear combination of the centered variables $(\xi_r^2 - 1)$ with coefficients the eigenvalues of $M$. Since $\sum_r \lambda_r^2 = \left\lVert M\right\rVert_\mathrm{F}^2 = 1$, standard bounds for Gaussian quadratic forms (Hanson--Wright) give
    \begin{equation}
        \sup_{y \in S^{p-1}} \left\lVert \left\langle X_j^{(i)},y\right\rangle\right\rVert_{\psi_1} \leq C.
    \end{equation}
    Moreover,
    \begin{equation}
        \frac{\left\lVert X_j^{(i)}\right\rVert^2}{p} = \left\lVert v_j^{(i)}\right\rVert^2,
    \end{equation}
    and for the rank-one columns this equals
    \begin{equation}
        \frac{\left\lVert x_j\right\rVert^4 - 2 \left\lVert x_j\right\rVert^2 + d}{d(d + 1)}.
    \end{equation}
    So for the Gaussian columns, we have from sub-gaussianity
    \begin{equation}
        \mathbb P\left(\left\lVert X^{(i)}_j\right\rVert \,>\, 2\sqrt{p} \right) \,\leq\, 2e^{-cp}, \quad j \,<\, i,
    \end{equation}
    and for the rank-one columns, we have from the expression above and a $\chi_d^2$ tail bound (which is sub-exponential)
    \begin{equation}
        \mathbb P\left(\left\lVert X^{(i)}_j\right\rVert \,>\, 2\sqrt{p} \right) \,\leq\, 2 e^{-c\sqrt{p}}, \quad j \,>\, i.
    \end{equation}
    Since $n\leq C_0p$, a union bound over the $n$ columns shows that the boundedness condition from \cite[Eq. 3]{1012.0294} holds uniformly in $i$ for $V_i$ with a deterministic constant $K$,
    \begin{equation}\label{eq:boundedness-event}
        \mathbb P \left(
        \max_{j\ne i}\frac{\left\lVert X_j^{(i)}\right\rVert}{\sqrt p} > K\max\left\{1,\left(\frac{n-1}{p}\right)^{1/4}\right\}
    \right) \leq e^{-c\sqrt{p}}.
    \end{equation}
    Therefore, the independent columns of $V_i$ satisfy the conditions of Lemma \ref{lem:adamczak-opnorm} \cite[Thm. 2]{1012.0294} with constants independent of $i$.
    With $A_i \mathrel{\mathop{:}}= \sqrt{p} V_i$, we have
    \begin{equation}\label{eq:operator-bound-prob}
        \mathbb P\left(\|A_i\|_\mathrm{op} > C \sqrt{\max\{p, n\}} + 6 \max_{j\neq i}\left\lVert X_j^{(i)}\right\rVert \right) \leq e^{-c\sqrt{p}}.
    \end{equation}
    From \eqref{eq:boundedness-event} and \eqref{eq:operator-bound-prob}, we have
    \begin{equation}
        \mathbb P\left(\left\lVert A_i\right\rVert_\mathrm{op} > C \sqrt{p} \right) \leq 2 e^{-c\sqrt{p}}.
    \end{equation}
    This is equivalent to $\mathbb P(\left\lVert K_i\right\rVert_\mathrm{op} > C) \leq 2 e^{-c\sqrt{p}}$.
    To obtain moment bounds from this probability estimate, we also control $\|K_i\|_\mathrm{op}$ on the exceptional event. Since $K_i$ is positive semidefinite,
    \begin{equation}
        \left\lVert K_i\right\rVert_{\mathrm{op}}\le \mathrm{Tr}(K_i)
        =\,\sum_{j\,<\,i}\left\lVert \widetilde f_j\right\rVert^2+\sum_{j\,>\,i}\left\lVert f_j\right\rVert^2.
    \end{equation}
    By the one-column bounds proved above and Minkowski,
    \begin{equation}
        \big\|\mathrm{Tr}(K_i)\big\|_{L^{2m}}
        \le \sum_{j<i}\left\lVert \widetilde f_j\right\rVert^2_{L^{2m}}
        +\sum_{j>i}\left\lVert f_j\right\rVert^2_{L^{2m}}
        \le C_m n
        \le C_m d^2.
    \end{equation}
    Let $E_i=\{\left\lVert K_i\right\rVert_{\mathrm{op}}\le C\}$. Then by Cauchy--Schwarz
    \begin{equation}
        \mathbb{E}\left\lVert K_i\right\rVert_{\mathrm{op}}^m
        \le C^m+\mathbb{E}\big[\mathrm{Tr}(K_i)^m\mathbb I_{E_i^c}\big]
        \le C^m+\big\|\mathrm{Tr}(K_i)\big\|_{L^{2m}}^m\mathbb P(E_i^c)^{1/2}
        \le C_m,
    \end{equation}
    for all sufficiently large $p$. So
    \begin{equation}
    \left\lVert K_i\right\rVert_{L^m(\mathrm{op})}\le C_m.
    \end{equation}

    Conditioned on $F_{\setminus i}$, the vector $F_{\setminus i}\epsilon$ is Gaussian with covariance $K_i$. Let $(\lambda_1, \ldots, \lambda_r$ be the eigenvalues of $K_i$. Hence
    \begin{equation}
        \begin{aligned}
        \mathbb{E}\left[\left\lVert F_{\setminus i}\epsilon\right\rVert^{2m}\mid F_{\setminus i}\right]
        &= \mathbb{E}\left[ \left( \sum_{j = 1}^r \lambda_j g_j^2\right)^m\right], \qquad g_j \stackrel{i.i.d}{\sim} \mathcal{N}(0, 1) \\
        &=\, \sum_{\alpha_1 + \cdots + \alpha_r \,=\, m} \binom{m}{\alpha_1, \ldots, \alpha_r} \prod_{j \,=\, 1}^t \lambda_j^{\alpha_j} \mathbb{E}[g_j^{2\alpha_j}]
        \end{aligned}
    \end{equation}
    But $\prod_{j = 1}^r \mathbb{E}[g_j^{2\alpha_j}] \le C_m$. Therefore,
    \begin{equation}
         \mathbb{E}\left[\left\lVert F_{\setminus i}\epsilon\right\rVert^{2m}\mid F_{\setminus i}\right] \,\le\, C_m \sum_{\alpha_1+ \ldots+ \alpha_r \,=\, m} \binom{m}{\alpha_1, \ldots, \alpha_r} \prod_{j \,=\, 1}^r \lambda_j^{\alpha_j} \,=\, C_m \left( \sum_{j \,=\, 1}^r \lambda_j \right)^m \,=\, C_m \mathrm{Tr}(K_i)^m
    \end{equation}
    Using again
    \begin{equation}
        \mathrm{Tr}(K_i)\,=\,\sum_{j\,<\,i}\left\lVert \widetilde f_j\right\rVert^2+\sum_{j\,>\,i}\left\lVert f_j\right\rVert^2
    \end{equation}
    and the bound $n\leq C_0p=\mathcal{O}(d^2)$, we obtain $\|\mathrm{Tr}(K_i)\|_{L^m}\le C_m d^2$. Taking expectations gives
    \begin{equation}
        \left\lVert F_{\setminus i}\epsilon\right\rVert_{L^m}\le C_m d.
    \end{equation}
    This completes the proof.

Since $u$ is independent of $\mathcal G_i$, it is enough to prove the deterministic version.
    \noindent \emph{Gaussian column.}
    If $u=\widetilde f_i$, then $u\sim N(0,I_p/p)$. The identities \eqref{eq:linear-moment-1}--\eqref{eq:linear-moment-2} are immediate. The bound \eqref{eq:linear-moment-lm} follows from the fact that $\left\langle u,a\right\rangle$ is centered Gaussian with variance $p^{-1}\left\lVert a\right\rVert^2$. For \eqref{eq:quadratic-moment-lm}, only the symmetric part of $A$ matters:
    \begin{equation}
        \left\langle u,Au\right\rangle=\left\langle u,A_{\mathrm s}u\right\rangle
    \end{equation}
    where $A_s = \frac{A + A^\top}{2}$.

    The centered quadratic form
    \begin{equation}
        \left\langle u,A_{\mathrm s}u\right\rangle-\frac1p\mathrm{Tr} A_{\mathrm s}
    \end{equation}
    has variance
    \begin{equation}
        \text{Var}\left(\left\langle u,A_{\mathrm s}u\right\rangle\right)
        =\frac{2}{p^2}\mathrm{Tr}(A_{\mathrm s}^2)
        \le \frac{2}{p}\left\lVert A_{\mathrm s}\right\rVert_{\mathrm{op}}^2
        \le C d^{-2}\left\lVert A_{\mathrm s}\right\rVert_{\mathrm{op}}^2
    \end{equation}
    Gaussian hypercontractivity gives
    \begin{equation}
        \left\|\left\langle u,Au\right\rangle-\frac1p\mathrm{Tr} A\right\|_{L^m}\le C_m d^{-1}\left\lVert A_{\mathrm s}\right\rVert_{\mathrm{op}},
    \end{equation}
    which is even better than \eqref{eq:quadratic-moment-lm}.
    \noindent \emph{Rank-one column.}
    Now let $u=f_i$. Write
    \begin{equation}
        Y\mathrel{\mathop{:}}= \frac{x_ix_i^\top-I_d}{\sqrt{d(d+1)}}\in\textsf{Sym}_d,
        \qquad
        u=\operatorname{vec}(Y)
        \qquad
        x_i\sim N(0,I_d)
    \end{equation}
    Let $M=\mathrm{mat}(a)\in\textsf{Sym}_d$. Then
    \begin{equation}\label{eq:linear-form-r1}
        \left\langle u,a\right\rangle
        =\mathrm{Tr}(YM)
        =\frac{x_i^\top Mx_i-\mathrm{Tr} M}{\sqrt{d(d+1)}}.
    \end{equation}
    This is a centered Gaussian quadratic form, so \eqref{eq:linear-moment-1} holds. Also,
    \begin{equation}
        \mathbb{E}\left[\left\langle u,a\right\rangle\left\langle u,b\right\rangle\right]
        =\frac{2}{d(d+1)}\mathrm{Tr}(\mathrm{mat}(a)\mathrm{mat}(b))
        =\frac1p\left\langle a,b\right\rangle,
    \end{equation}
    which is \eqref{eq:linear-moment-2}. Since
    \begin{equation}
        \text{Var}(x_i^\top Mx_i-\mathrm{Tr} M)=2\left\lVert M\right\rVert_{\mathrm{F}}^2=2\left\lVert a\right\rVert^2,
    \end{equation}
    hypercontractivity for Gaussian quadratic forms gives \eqref{eq:linear-moment-lm}.

    It remains to prove \eqref{eq:quadratic-moment-lm}. Let $\mathscr{A}:\textsf{Sym}_d\to\textsf{Sym}_d$ be the self-adjoint operator
    \begin{equation}
        \mathscr{A}(H)\mathrel{\mathop{:}}= \mathrm{mat}(A_{\mathrm s}\operatorname{vec}(H)).
    \end{equation}
    Because $\operatorname{vec}$ is an isometry,
    \begin{equation}
        \left\lVert \mathscr{A}\right\rVert_{\mathrm{F}\to\mathrm{F}}=\left\lVert A_{\mathrm s}\right\rVert_{\mathrm{op}}.
    \end{equation}
    Using $u=\operatorname{vec}(Y)$,
    \begin{equation}
        \left\langle u,Au\right\rangle=\left\langle Y,\mathscr{A} Y\right\rangle.
    \end{equation}
    By the covariance identity \eqref{eq:column-covariance},
    \begin{equation}
        \mathbb{E}\left\langle Y,\mathscr{A} Y\right\rangle
        =\frac1p\mathrm{Tr}(A_{\mathrm s})
        =\frac1p\mathrm{Tr} A.
    \end{equation}

    Write $Y_0=x_ix_i^\top-I_d$, so that $Y=Y_0/\sqrt{d(d+1)}$, and define
    \begin{equation}
        g(x_i)\mathrel{\mathop{:}}= \frac{1}{d(d+1)}\left\langle Y_0,\mathscr{A} Y_0\right\rangle.
    \end{equation}
    Then
    \begin{equation}
        g(x_i)=\left\langle u,Au\right\rangle.
    \end{equation}
    A direct differentiation gives, for every $h\in\mathbb R^d$,
    \begin{equation}
        Dg(x_i)[h]
        =\frac{4}{d(d+1)}\left\langle h,\mathscr{A}(Y_0)x_i\right\rangle,
    \end{equation}
    hence
    \begin{equation}
        \left\lVert \nabla g(x_i)\right\rVert
        \le \frac{4}{d(d+1)}\left\lVert \mathscr{A}\right\rVert_{F\to F}\left\lVert Y_0\right\rVert_{\mathrm{F}}\left\lVert x_i\right\rVert
        \le \frac{4}{d(d+1)}\left\lVert A_{\mathrm s}\right\rVert_{\mathrm{op}}\left\lVert Y_0\right\rVert_{\mathrm{F}}\left\lVert x_i\right\rVert.
    \end{equation}
    Let $S=\left\lVert x_i\right\rVert^2\sim \chi_d^2$. Since
    \begin{equation}
        \left\lVert Y_0\right\rVert_{\mathrm{F}}^2=S^2-2S+d,
    \end{equation}
    we obtain
    \begin{equation}
        \mathbb{E}\big[\left\lVert Y_0\right\rVert_{\mathrm{F}}^2\left\lVert x_i\right\rVert^2\big]
        =\mathbb{E}[S^3-2S^2+dS]
        =d^3+5d^2+4d
        \le C d^3.
    \end{equation}
    The Gaussian Poincar\'e inequality therefore gives
    \begin{equation}
        \text{Var}(g)\le \mathbb{E}\left\lVert \nabla g\right\rVert^2\le C d^{-1}\left\lVert A_{\mathrm s}\right\rVert_{\mathrm{op}}^2.
    \end{equation}
    Since $g-\mathbb{E} g$ is a polynomial of degree at most four in $x_i$, Gaussian hypercontractivity yields
    \begin{equation}
        \left\|\left\langle u,Au\right\rangle-\frac1p\mathrm{Tr} A\right\|_{L^m}
        \le C_m \|g-\mathbb{E} g\|_{L^2}
        \le C_m d^{-1/2}\left\lVert A_{\mathrm s}\right\rVert_{\mathrm{op}}.
    \end{equation}
    This proves \eqref{eq:quadratic-moment-lm}. The unconditional estimates \eqref{eq:linear-moment-uncond}--\eqref{eq:quadratic-moment-uncond} follow by taking expectations and using $p\asymp d^2$.

Fix $r \ge 2$, we write
    \begin{equation}
        A(t) \,\mathrel{\mathop{:}}=\, \sum_{j \,=\, 1}^r t_j M_j, \quad t \,=\, (t_1, \ldots, t_r) \,\in\, \mathbb R^r
    \end{equation}
    Choose $t$ such that $\left\lVert A(t)\right\rVert_\mathrm{op} < 1/2$. We thus have
    \begin{equation}
        \mathbb{E} \exp\left( \sum_{j=1}^r t_j q_{M_j}(x) \right) = \exp\left(-\mathrm{Tr}(A(t))\right) \det(I_d - 2A(t))^{-1/2}
    \end{equation}
    The cumulant-generating function has the Taylor expansion
    \begin{equation}
        \begin{aligned}
            K(t) &\mathrel{\mathop{:}}=\, \log \mathbb{E}\exp\left( \sum_{j\,=\,1}^r t_j q_{M_j}(x) \right) \,=\, -\mathrm{Tr} A(t) - \frac 1 2 \mathrm{Tr} \log(I_d - 2A(t)) \\
            &=\, -\mathrm{Tr} A(t) + \frac 1 2 \sum_{m\,=\,1}^\infty \frac{2^m}{m}\mathrm{Tr}(A(t)^m) \,=\, \sum_{m \,=\, 2}^\infty \frac{2^{m-1}}{m} \mathrm{Tr}(A(t)^m)
        \end{aligned}
    \end{equation}
    But the joint cumulants are given by the mixed derivative
    \begin{equation}
        \kappa\left(q_{M_1}(x), \ldots, q_{M_r}(x) \right) = \partial_{t_1} \cdots \partial_{t_r} K(t) \ \Big|_{t=0}
    \end{equation}
    But observe that $\frac{2^{m-1}}{m} \mathrm{Tr}(A(t)^m)$ is a polynomial of degree $m$ in $t$. Therefore, only the term with $m = r$ contributes to the $r$th joint cumulant. We thus have
    \begin{equation}
        \kappa\left(q_{M_1}(x), \ldots, q_{M_r}(x) \right) \,=\, \frac{2^{r-1}}{r} \sum_{\sigma \,\in\, S_r} \mathrm{Tr}\left( M_{\sigma(1)} \cdots M_{\sigma(r)} \right)
    \end{equation}
    Since trace is invariant under cyclic permutations, every cyclic class in $S_r$ contributes the same value to the sum and contains $r - 1$ permutations. Grouping the sum over $S_r$ into cyclic classes therefore gives the stated formula.

Since $u$ is independent of $\mathcal{G}_i$, it is enough to prove the deterministic version.

    \noindent \emph{Gaussian column.}
    If $u = \widetilde f_i$, then $u \sim \mathcal{N}(0, I_p/p)$. Note that
    \begin{equation}
        \left\langle u,Au\right\rangle - \frac 1 p \mathrm{Tr} A = \left\langle u,A_{\mathrm s}u\right\rangle - \frac 1 p \mathrm{Tr} A_{\mathrm s}.
    \end{equation}
    This is a centered Gaussian quadratic form with variance
    \begin{equation}
        \text{Var}(\left\langle u,A_{\mathrm s}u\right\rangle) \,=\, \frac{2}{p^2} \mathrm{Tr}(A_{\mathrm s}^2) \,=\, \frac{2}{p^2} \left\lVert A_{\mathrm s}\right\rVert_{\mathrm{F}}^2.
    \end{equation}
    Gaussian hypercontractivity therefore gives
    \begin{equation}
        \left\lVert \left\langle u,Au\right\rangle - \frac 1 p \mathrm{Tr} A\right\rVert_{L^m} \,\le\, C_m p^{-1} \left\lVert A_{\mathrm s}\right\rVert_{\mathrm{F}} \,\le\, C_m d^{-2} \left\lVert A_{\mathrm s}\right\rVert_{\mathrm{F}},
    \end{equation}
    which is stronger than the claimed bound.

    \noindent \emph{Rank-one column.}
    Now let $u = f_i$. Write
    \begin{equation}
        Y \mathrel{\mathop{:}}= \frac{xx^\top - I_d}{\sqrt{d(d+1)}} \in \textsf{Sym}_d,
        \qquad
        u = \operatorname{vec}(Y),
        \qquad
        x \sim \mathcal{N}(0, I_d),
    \end{equation}
    and let $Y_0 = xx^\top - I_d$, so that $Y = Y_0 / \sqrt{d(d+1)}$. Recall the self-adjoint operator $\mathscr{A} : \textsf{Sym}_d \to \textsf{Sym}_d$ defined by
    \begin{equation}
        \mathscr{A}(H) \mathrel{\mathop{:}}= \mathrm{mat}(A_{\mathrm s} \operatorname{vec}(H)).
    \end{equation}
    Choose a Frobenius-orthonormal eigenbasis $(E_\alpha)_{\alpha = 1}^p$ of $\textsf{Sym}_d$ such that
    \begin{equation}
        \mathscr{A}(E_\alpha) = \lambda_\alpha E_\alpha,
        \qquad \alpha = 1, \ldots, p.
    \end{equation}
    Since $\operatorname{vec} \circ \mathscr{A} \circ \mathrm{mat} = A_{\mathrm s}$, the eigenvalues of $\mathscr{A}$ are the eigenvalues of $A_{\mathrm s}$. Therefore,
    \begin{equation}
        \sum_{\alpha = 1}^p \lambda_\alpha^2 = \left\lVert A_{\mathrm s}\right\rVert_{\mathrm{F}}^2,
        \qquad
        \sum_{\alpha \,=\, 1}^p \lambda_\alpha \,=\, \mathrm{Tr} A_{\mathrm s} \,=\, \mathrm{Tr} A.
    \end{equation}

    For each $\alpha$, define
    \begin{equation}
        q_\alpha \mathrel{\mathop{:}}= \left\langle Y_0,E_\alpha\right\rangle = x^\top E_\alpha x - \mathrm{Tr}(E_\alpha).
    \end{equation}
    By Lemma \ref{lem:gaussian-quad-cumulants} with $r = 2$,
    \begin{equation}
        \mathbb{E}[q_\alpha q_\beta] = 2 \mathrm{Tr}(E_\alpha E_\beta) = 2 \delta_{\alpha\beta}.
    \end{equation}
    In particular, $\mathbb{E}[q_\alpha^2] = 2$ for every $\alpha$. Since $Y_0 = \sum_{\alpha = 1}^p q_\alpha E_\alpha$, we have
    \begin{equation}
        \left\langle u,Au\right\rangle \,=\, \left\langle Y,\mathscr{A} Y\right\rangle \,=\, \frac{1}{d(d+1)} \sum_{\alpha \,=\, 1}^p \lambda_\alpha q_\alpha^2.
    \end{equation}
    Using $p = d(d+1)/2$, we also get
    \begin{equation}
        \frac 1 p \mathrm{Tr} A \,=\, \frac{2}{d(d+1)} \sum_{\alpha \,=\, 1}^p \lambda_\alpha \,=\, \frac{1}{d(d+1)} \sum_{\alpha \,=\, 1}^p \lambda_\alpha \mathbb{E}[q_\alpha^2].
    \end{equation}
    Hence
    \begin{equation}
        \left\langle u,Au\right\rangle - \frac 1 p \mathrm{Tr} A = \frac{1}{d(d+1)} g(x),
        \qquad
        g(x) \mathrel{\mathop{:}}= \sum_{\alpha = 1}^p \lambda_\alpha (q_\alpha^2 - 2).
    \end{equation}
    The random variable $g(x)$ is a polynomial of degree four in the Gaussian vector $x$, so Gaussian hypercontractivity gives
    \begin{equation}
        \left\lVert g(x)\right\rVert_{L^m} \le C_m \left\lVert g(x)\right\rVert_{L^2}.
    \end{equation}

    It remains to bound $\text{Var}(g)$. Since each $q_\alpha$ is centered, the moment-cumulant formula gives
    \begin{equation}
        \text{Cov}(q_\alpha^2, q_\beta^2) = 2\kappa_2(q_\alpha, q_\beta)^2 + \kappa_4(q_\alpha, q_\alpha, q_\beta, q_\beta).
    \end{equation}
    By the previous display,
    \begin{equation}
        2\kappa_2(q_\alpha, q_\beta)^2 = 8\delta_{\alpha\beta}.
    \end{equation}
    By Lemma \ref{lem:gaussian-quad-cumulants} with $r = 4$, the fourth cumulant is a finite sum of traces of cyclic words of length four in $E_\alpha$ and $E_\beta$. Every such word is either of the form $E_\alpha^2 E_\beta^2$ or $E_\alpha E_\beta E_\alpha E_\beta$. Therefore,
    \begin{equation}
        \left|\kappa_4(q_\alpha, q_\alpha, q_\beta, q_\beta)\right|
        \le C \left(\mathrm{Tr}(E_\alpha^2 E_\beta^2) + \left|\mathrm{Tr}(E_\alpha E_\beta E_\alpha E_\beta)\right|\right).
    \end{equation}
    Since $E_\alpha$ and $E_\beta$ are symmetric, Cauchy--Schwarz gives
    \begin{equation}
        \left|\mathrm{Tr}(E_\alpha E_\beta E_\alpha E_\beta)\right|
        = \left|\mathrm{Tr}((E_\beta E_\alpha)(E_\alpha E_\beta))\right|
        \le \left\lVert E_\beta E_\alpha\right\rVert_{\mathrm{F}} \left\lVert E_\alpha E_\beta\right\rVert_{\mathrm{F}}
        = \mathrm{Tr}(E_\alpha^2 E_\beta^2).
    \end{equation}
    Hence
    \begin{equation}
        \left|\text{Cov}(q_\alpha^2, q_\beta^2)\right| \le C \left(\delta_{\alpha\beta} + \mathrm{Tr}(E_\alpha^2 E_\beta^2)\right).
    \end{equation}
    Expanding the variance of $g$ gives
    \begin{equation}
        \text{Var}(g) \,\le\, C \sum_{\alpha \,=\, 1}^p \lambda_\alpha^2 + C \sum_{\alpha, \beta \,=\, 1}^p |\lambda_\alpha \lambda_\beta| \mathrm{Tr}(E_\alpha^2 E_\beta^2).
    \end{equation}

    To control the double sum, note first that $\sum_{\beta = 1}^p E_\beta^2$ does not depend on the choice of Frobenius-orthonormal basis of $\textsf{Sym}_d$. To see this, if $(\widetilde E_\beta)_{\beta = 1}^p$ is another such basis and $\widetilde E_\beta = \sum_{\gamma = 1}^p O_{\beta\gamma} E_\gamma$ for some $O \in O(p)$, then
    \begin{equation}
        \sum_{\beta \,=\, 1}^p \widetilde E_\beta^2 \,=\, \sum_{\beta, \gamma, \eta \,=\, 1}^p O_{\beta\gamma} O_{\beta\eta} E_\gamma E_\eta \,=\, \sum_{\gamma \,=\, 1}^p E_\gamma^2.
    \end{equation}
    Therefore we may compute this sum using the standard symmetric basis
    \begin{equation}
        F_{aa} = e_a e_a^\top,
        \qquad
        F_{ab} = \frac{e_a e_b^\top + e_b e_a^\top}{\sqrt 2},
        \qquad 1 \,\le\, a \,<\, b \,\le\, d.
    \end{equation}
    A direct calculation gives
    \begin{equation}
        \sum_{\beta = 1}^p E_\beta^2 = \frac{d+1}{2} I_d.
    \end{equation}

    Now set $T_{\alpha\beta} \mathrel{\mathop{:}}= \mathrm{Tr}(E_\alpha^2 E_\beta^2) \ge 0$. By Cauchy--Schwarz,
    \begin{equation}
        \begin{aligned}
            \sum_{\alpha, \beta = 1}^p |\lambda_\alpha \lambda_\beta| T_{\alpha\beta}
            &\le \left(\sum_{\alpha, \beta = 1}^p \lambda_\alpha^2 T_{\alpha\beta}\right)^{1/2}
            \left(\sum_{\alpha, \beta \,=\, 1}^p \lambda_\beta^2 T_{\alpha\beta}\right)^{1/2}\,=\, \sum_{\alpha, \beta \,=\, 1}^p \lambda_\alpha^2 T_{\alpha\beta} \\
            &=\, \sum_{\alpha \,=\, 1}^p \lambda_\alpha^2 \mathrm{Tr}\left(E_\alpha^2 \sum_{\beta \,=\, 1}^p E_\beta^2\right) \,=\, \frac{d+1}{2} \sum_{\alpha \,=\, 1}^p \lambda_\alpha^2.
        \end{aligned}
    \end{equation}
    We obtain
    \begin{equation}
        \text{Var}(g) \,\le\, C d \sum_{\alpha \,=\, 1}^p \lambda_\alpha^2 \,=\, C d \left\lVert A_{\mathrm s}\right\rVert_{\mathrm{F}}^2.
    \end{equation}
    Therefore,
    \begin{equation}
        \left\lVert \left\langle u,Au\right\rangle - \frac 1 p \mathrm{Tr} A\right\rVert_{L^m}
        \le \frac{C_m}{d(d+1)} d^{1/2} \left\lVert A_{\mathrm s}\right\rVert_{\mathrm{F}}
        \le C_m d^{-3/2} \left\lVert A_{\mathrm s}\right\rVert_{\mathrm{F}}.
    \end{equation}

    This proves the deterministic estimate. Averaging over $\mathcal{G}_i$, we get
    \begin{equation}
        \left\lVert \left\langle u,Au\right\rangle - \frac 1 p \mathrm{Tr} A\right\rVert_{L^m}
        \le C_m d^{-3/2} \left\lVert A_{\mathrm s}\right\rVert_{L^m(\mathrm{F})}
        \le C_m d^{-3/2} \left\lVert A\right\rVert_{L^{2m}(\mathrm{F})},
    \end{equation}
    which proves the first claim. The second follows from $\left\lVert A_{\mathrm s}\right\rVert_{L^{2m}(\mathrm{F})} \le \left\lVert A\right\rVert_{L^{2m}(\mathrm{F})}$.

For $t = 0$, we clearly have $q^0(u) = 0$ because the iterates start at the same place. By \eqref{eq:w-exact} of Proposition \ref{prop:exact-loo}, we have
    \begin{equation}
        w^0(u) = u \left(\kappa_0 \left\langle u,{\mathbf s}^* - \widehat{\mathbf s}^0\right\rangle + \nu_0 \epsilon_i \right)
    \end{equation}
    But by Assumption \ref{ass:signal-init}, by triangle inequality,
    \begin{equation}
        \left\lVert {\mathbf s}^* - \widehat{\mathbf s}^0\right\rVert \leq C \sqrt{d}
    \end{equation}
    From \eqref{eq:linear-moment-uncond} of Lemma \ref{lem:one-column-moments} with $a = {\mathbf s}^* - \widehat{\mathbf s}^0$, we have
    \begin{equation}
        \left\lVert \left\langle u,{\mathbf s}^* - \widehat{\mathbf s}^0\right\rangle\right\rVert_{L^{2m}} \,\leq\, C_m d^{-1} \left\lVert {\mathbf s}^* - \widehat{\mathbf s}^0\right\rVert_{L^{2m}} \,\leq\, C_m d^{-1/2}
    \end{equation}
    Since we also have $\mathbb{E} \left\lVert u\right\rVert^m \leq C_m$ and $\nu_0 \epsilon_i = \mathcal{O}_{L^m}(d^{-1/2})$, we have
    \begin{equation}
        \left\lVert w^0(u)\right\rVert_{L^m} \leq C_m d^{-1/2}
    \end{equation}
    Therefore, $\left\lVert m^0(u)\right\rVert_{L^m} \leq C_m d^{-1/2}$. Then by \eqref{eq:q-linearized} and Proposition \ref{prop:exact-loo}, we have
    \begin{equation}
        \left\lVert q^1(u)\right\rVert_{L^m} \,\leq\, \left\lVert L^0_i\right\rVert_\mathrm{op} \left\lVert m^0(u)\right\rVert_{L^m} + \left\lVert \varepsilon^0_i(u)\right\rVert_{L^m} \,\leq\, C_m d^{-1/2} + C_m \left\lVert m^0(u)\right\rVert_{L^{2m}}^2 \,\leq\, C_m d^{-1/2}
    \end{equation}
    where we used Lemma \ref{lem:dk-bounds} for $\left\lVert L^0_i\right\rVert_\mathrm{op}$.

    The same estimate gives $\left\lVert \varepsilon_i^0(u)\right\rVert_{L^m}\le C_m d^{-1}$. We proceed by induction. Assume that for some $t$ and every $m$,
    \begin{equation}
        \max_{s \,\le\, t} \left\lVert q^s(u)\right\rVert_{L^m} + \max_{s \,\le\, t - 1} \left\lVert w^s(u)\right\rVert_{L^m} \,\leq\, C_m d^{-1/2}
    \end{equation}
    Then by \eqref{eq:beta-exact} of Proposition \ref{prop:exact-loo}, we have
    \begin{equation}
        \beta^t_i(u) = \kappa_t \left\langle u,{\mathbf s}^* - \widehat{\mathbf s}^t_{\setminus i}\right\rangle - \kappa_t \left\langle u,q^t(u)\right\rangle + \nu_t \epsilon_i
    \end{equation}
    Applying \eqref{eq:linear-moment-uncond} from Lemma \ref{lem:one-column-moments}, now with $a = {\mathbf s}^* - \widehat{\mathbf s}^t_{\setminus i}$, using Lemma \ref{lem:base-det-bounds}, we have
    \begin{equation}
        \left\lVert \left\langle u,{\mathbf s}^* - \widehat{\mathbf s}^t_{\setminus i}\right\rangle\right\rVert_{L^{2m}} \,\le\, C_m d^{-1} \left\lVert {\mathbf s}^* - \widehat{\mathbf s}^t_{\setminus i}\right\rVert_{L^{2m}} \,\le\, C_m d^{-1/2}
    \end{equation}
    Now $ \kappa_t \left\langle u,q^t(u)\right\rangle$ is bounded by Cauchy--Schwarz
    \begin{equation}
        \left\lVert u\right\rVert_{L^{2m}} \left\lVert q^t(u)\right\rVert_{L^{2m}} \le C_m d^{-1/2}
    \end{equation}
    So $\left\lVert \beta^t_i(u)\right\rVert_{L^m} \le C_m d^{-1/2}$. Therefore, by \eqref{eq:w-exact} of Proposition \ref{prop:exact-loo}, Lemma \ref{lem:sensing-envelope}, and the induction hypothesis,
    \begin{equation}
        \begin{aligned}
            \left\lVert w^t(u)\right\rVert_{L^m} &\le\, |\kappa_t| \left\lVert K_i\right\rVert_{L^{2m}(\mathrm{op})} \left\lVert q^t(u)\right\rVert_{L^{2m}} + |\rho_t| \left\lVert w^{t - 1}(u)\right\rVert_{L^m} + \left\lVert u\right\rVert_{L^{2m}} \left\lVert \beta^t_i(u)\right\rVert_{L^{2m}} \,\leq\, C_m d^{-1/2}
        \end{aligned}
    \end{equation}
    Therefore, we have $\left\lVert  m^t(u)\right\rVert_{L^m} \le C_m d^{-1/2}$. By \eqref{eq:q-linearized} of Proposition \ref{prop:exact-loo}, we have
    \begin{equation}
        \left\lVert q^{t + 1}(u)\right\rVert_{L^m} \le C_m d^{-1/2}+ C_m\left\lVert m^t(u)\right\rVert_{L^{2m}}^2 \le C_m d^{-1/2}
    \end{equation}
    Lastly,
    \begin{equation}
        \left\lVert \varepsilon^t_i(u)\right\rVert_{L^m} \le C \left\lVert m^t(u)\right\rVert_{L^{2m}}^2 \le C_m d^{-1}
    \end{equation}
    So by induction, the claim follows.

Let $\widetilde F=[\widetilde f_1,\ldots,\widetilde f_n]\in\mathbb R^{p\times n}$ be the Gaussian feature matrix of \eqref{eq:gaussian-surrogate-features}, and set
    \begin{equation}\label{eq:se-proof-scaled-variables}
        A_d\mathrel{\mathop{:}}=\sqrt{\frac pn}\,\widetilde F^\top,
        \qquad
        \lambda_d\mathrel{\mathop{:}}=\sqrt{(d+1)\alpha_d},
        \qquad
        \theta^\star\mathrel{\mathop{:}}=\lambda_d\operatorname{vec}(S^\star),
        \qquad
        \widehat\theta^t\mathrel{\mathop{:}}=\lambda_d\operatorname{vec}(\widehat S_{\mathrm G}^t).
    \end{equation}
    The entries of $A_d$ are independent $\mathcal{N}(0,1/n)$ variables, $A_d\theta^\star=\mathcal{A}_{\mathrm G}(S^\star)$, and $y_{\mathrm G}=A_d\theta^\star+\epsilon$. Define
    \begin{equation*}
        \eta_{t,d}(x)\mathrel{\mathop{:}}=
        \lambda_d\operatorname{vec}\left(\sigma_t\left(\text{mat}(x/\lambda_d)\right)\right),
        \qquad
        \mathfrak r^t\mathrel{\mathop{:}}=\gamma_t r^t_{\mathrm G},
        \qquad
        \overline b_t\mathrel{\mathop{:}}= b_t/\gamma_{t-1}\quad(t\geq1).
    \end{equation*}
    Using $c_t/\gamma_t=p/(n(d+1))$, the Gaussian recursion \eqref{eq:AMP-recursion} becomes
    \begin{equation}\label{eq:se-proof-standard-amp}
        \mathfrak r^t
        =y_{\mathrm G}-A_d\widehat\theta^t+\overline b_t\mathfrak r^{t-1},
        \qquad
        \widehat\theta^{t+1}
        =\eta_{t,d}\big(\widehat\theta^t+A_d^\top\mathfrak r^t\big),
    \end{equation}
    with $\mathfrak r^{-1}=0$ and $\overline b_0=0$.

    We first match \eqref{eq:se-proof-standard-amp}, including its sign convention, to the asymmetric AMP recursion of \cite[Equations~(27)--(29)]{BerthierRaphael2020Sefa}. Let $\eta_{-1,d}(x)\mathrel{\mathop{:}}=\widehat\theta^0$ and define
    \begin{equation}\label{eq:se-proof-change-variables}
        e_t(u)\mathrel{\mathop{:}}=\eta_{t-1,d}(\theta^\star-u)-\theta^\star,
        \qquad
        g_t(v)\mathrel{\mathop{:}}= v-\epsilon,
    \end{equation}
    together with $u^0=0$ and
    \begin{equation}\label{eq:se-proof-bmn-variables}
        u^{t+1}\mathrel{\mathop{:}}=\theta^\star-\big(\widehat\theta^t+A_d^\top\mathfrak r^t\big),
        \qquad
        v^t\mathrel{\mathop{:}}=\epsilon-\mathfrak r^t.
    \end{equation}
    Then $e_t(u^t)=\widehat\theta^t-\theta^\star$ and $g_t(v^t)=-\mathfrak r^t$, and \eqref{eq:se-proof-standard-amp} is equivalent to
    \begin{equation}\label{eq:se-proof-bmn-recursion}
        u^{t+1}=A_d^\top g_t(v^t)-e_t(u^t),
        \qquad
        v^t=A_de_t(u^t)+\overline b_tg_{t-1}(v^{t-1}),
    \end{equation}
    with $g_{-1}=0$. Thus the output-side Onsager coefficient in \cite{BerthierRaphael2020Sefa} is $d_t=1$, while its input-side coefficient is $b_t^{\mathrm{BMN}}=-\overline b_t$.

    The spectral map induced by $\sigma_t$ is Lipschitz in Frobenius norm with constant $\left\lVert \sigma_t'\right\rVert_\infty$. Since $\operatorname{vec}$ is an isometry, the maps $\eta_{t,d}$, and hence $e_t$, are uniformly Lipschitz in Euclidean norm; the maps $g_t$ are $1$-Lipschitz. Moreover,
    \begin{equation}\label{eq:se-proof-divergence-identification}
        \div\eta_{t,d}(x)
        =\mathcal D_t\big(\text{mat}(x/\lambda_d)\big).
    \end{equation}
    The map $e_0$ is constant, and for $t\geq1$,
    \begin{equation*}
        \frac1n\mathbb{E}\div e_t(Z)
        =-\frac1n\mathbb{E}\mathcal D_{t-1}(\overline R^{t-1})
        =-\frac{b_t}{\gamma_{t-1}}
        =-\overline b_t,
    \end{equation*}
    where the centered Gaussian input may be replaced by its negative without changing its covariance. This is precisely the Onsager coefficient in \eqref{eq:se-proof-bmn-recursion}; the sign is therefore accounted for explicitly.

    It remains to identify the covariance recursion. Let $(U^0,\ldots,U^t)$ be centered jointly Gaussian vectors in $\mathbb R^p$ with
    \begin{equation*}
        \mathbb{E}[U^s(U^r)^\top]=Q_{s,r}I_p,
        \qquad
        W^r\mathrel{\mathop{:}}=\text{mat}(U^r)/\lambda_d.
    \end{equation*}
    Because off-diagonal coordinates of $\text{mat}(U^r)$ are divided by $\sqrt2$, the matrices $(W^0,\ldots,W^t)$ have exactly the entrywise covariance \eqref{eq:se-noise-covariance}. Furthermore,
    \begin{equation}\label{eq:se-proof-normalization-identity}
        \frac{\lambda_d^2}{n}=\frac{d+1}{p}=\frac2d.
    \end{equation}
    We condition on $S^\star$, $\widehat S^0$, and the probability-one event $n^{-1}\left\lVert \epsilon\right\rVert^2\to\Delta$. If $(Z_1,Z_2)$ is a centered Gaussian pair in $\mathbb R^n$ with cross-covariance $K_{12}I_n$, then
    \begin{equation}\label{eq:se-proof-output-overlap}
        \frac1n\mathbb{E}\langle g_s(Z_1),g_t(Z_2)\rangle
        =K_{12}+\frac1n\left\lVert \epsilon\right\rVert^2
        \longrightarrow K_{12}+\Delta.
    \end{equation}
    Write $\Sigma$ and $\mathsf T$ for the two covariance arrays in \cite[Equations~(25)--(26)]{BerthierRaphael2020Sefa}. We claim, inductively, that
    \begin{equation}\label{eq:se-proof-covariance-identification}
        \Sigma_{s,t}=C_{s,t},
        \qquad
        \mathsf T_{s+1,t+1}=Q_{s,t}.
    \end{equation}
    Indeed, \eqref{eq:se-proof-normalization-identity} gives
    \begin{equation*}
        \Sigma_{0,0}
        =\lim_{d\to\infty}\frac1n\left\lVert \widehat\theta^0-\theta^\star\right\rVert^2
        =C_{0,0},
    \end{equation*}
    and \eqref{eq:se-proof-output-overlap} then gives $\mathsf T_{1,1}=\Delta+C_{0,0}=Q_{0,0}$. If \eqref{eq:se-proof-covariance-identification} holds through time $t$, the Gaussian input to $e_{t+1}$ has covariance $Q$ and
    \begin{equation*}
        \frac1n\mathbb{E}\langle e_s(Z_s),e_{t+1}(Z_{t+1})\rangle
        =\frac2d\mathbb{E}\mathrm{Tr}\big((\overline S^s-S^\star)(\overline S^{t+1}-S^\star)\big)
        \longrightarrow C_{s,t+1},
    \end{equation*}
    where \eqref{eq:se-proof-normalization-identity} was used. Assumption~\ref{ass:se-regularity} supplies these limits for every covariance pair. Applying \eqref{eq:se-proof-output-overlap} once more gives $\mathsf T_{s+1,t+2}=C_{s,t+1}+\Delta=Q_{s,t+1}$, completing the induction. The remaining norm and overlap hypotheses of \cite[Theorem~1]{BerthierRaphael2020Sefa} follow from Assumptions~\ref{ass:signal-init} and \ref{ass:se-regularity} and the Lipschitz bounds above. That theorem therefore yields joint state evolution for the scaled residuals and pre-denoising matrices in \eqref{eq:se-proof-standard-amp}.

    We finally verify that the three observables are admissible test functions. For $\theta,\theta'\in\mathbb R^p$, set
    \begin{equation*}
        A\mathrel{\mathop{:}}=\sigma_t\big(\text{mat}(\theta/\lambda_d)\big),
        \qquad
        A'\mathrel{\mathop{:}}=\sigma_t\big(\text{mat}(\theta'/\lambda_d)\big).
    \end{equation*}
    Then
    \begin{equation}\label{eq:se-proof-spectral-lipschitz}
        \left\lVert A-A'\right\rVert_\mathrm{F}
        \leq\frac{\left\lVert \sigma_t'\right\rVert_\infty}{\lambda_d}\left\lVert \theta-\theta'\right\rVert.
    \end{equation}
    By Assumption~\ref{ass:signal-init}, \eqref{eq:se-proof-spectral-lipschitz}, and Cauchy--Schwarz,
    \begin{equation*}
        \frac1d\left\lvert \mathrm{Tr}((A-A')S^\star)\right\rvert
        \leq\frac{\left\lVert S^\star\right\rVert_\mathrm{F}\left\lVert \sigma_t'\right\rVert_\infty}{d\lambda_d}\left\lVert \theta-\theta'\right\rVert
        \leq\frac{C}{\sqrt n}\left\lVert \theta-\theta'\right\rVert,
    \end{equation*}
    where the last inequality uses \eqref{eq:se-proof-normalization-identity}. If $B$ is either $\widehat S^0$ or the output of a bounded spectral denoiser, then $\left\lVert B\right\rVert_\mathrm{F}\leq C\sqrt d$, and the same calculation with $S^\star$ replaced by $B$ applies to each argument of a cross-time overlap. Thus the signal and cross-time overlaps are uniformly Lipschitz functions of the scaled AMP coordinates under the normalized Euclidean metric of \cite{BerthierRaphael2020Sefa}. For the spectral statistic, order the eigenvalues of $A$ and $A'$ consistently. Lidskii's inequality \cite[Section~III.4]{Bhatia1997} and the trace-norm bound give
    \begin{equation*}
        \sum_{j=1}^d\left\lvert \lambda_j(A)-\lambda_j(A')\right\rvert
        \leq\left\lVert A-A'\right\rVert_{S_1}
        \leq\sqrt d\left\lVert A-A'\right\rVert_\mathrm{F}.
    \end{equation*}
    Since $\mu$ is Lipschitz on $I_\ast$,
    \begin{equation*}
        \frac1d\left\lvert \mathrm{Tr}\mu(A)-\mathrm{Tr}\mu(A')\right\rvert
        \leq\frac{\operatorname{Lip}_{I_\ast}(\mu)}{\sqrt d}\left\lVert A-A'\right\rVert_\mathrm{F}
        \leq\frac{C}{\sqrt n}\left\lVert \theta-\theta'\right\rVert.
    \end{equation*}
    Hence all three observables are uniformly pseudo-Lipschitz test functions. Their state-evolution expectations are exactly the predictions in \eqref{eq:se-predictions}; at $t=0$ the observables are deterministic and already equal to their predictions. This proves \eqref{eq:gaussian-se-observables}.
